insert into audit.data_sources (source_id, institution, dataset_name, official_title, source_url, source_language, frequency, methodology_notes, is_active) values
  ('BQK_RAPORT_MUJOR', 'BQK', 'Raporti Mujor i Sistemit të Pagesave', 'Monthly Report on Cash and Non-Cash Payment Instruments', 'https://bqk-kos.org/statistikat/?lang=en', 'sq/en', 'monthly', 'Terminal stock and transaction flows come from the same publication, so productivity ratios share a universe. Begins January 2025 and is not continuous with the annual report series.', TRUE),
  ('BQK_T15', 'BQK', 'Table 15 — Payment System', 'Payment System statistical time series, Table 15', 'https://bqk-kos.org/repository/docs/time_series/', 'sq/en', 'monthly', 'Long-run series. Counts published in thousands and values in EUR millions; both are scaled on load. No terminal stock exists on this basis.', TRUE),
  ('BQK_CARDS_ANNUAL', 'BQK', 'Use of Bank Cards in Kosovo', 'Use of Bank Cards in Kosovo — September 2025 edition', 'https://bqk-kos.org/repository/docs/SistemiIPagesave/Use%20of%20bank%20cards%20in%20Kosovo.pdf?lang=en', 'en', 'annual', 'City distribution read from charts, not from a published table. Figures 26 and 27 combine ATM AND POS transactions.', TRUE),
  ('ATK_QARKULLIMI_2019', 'ATK', 'Open Data — Qarkullimi 2019', 'Të dhëna të hapura — Qarkullimi 2019', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2020', 'ATK', 'Open Data — Qarkullimi 2020', 'Të dhëna të hapura — Qarkullimi 2020', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2021', 'ATK', 'Open Data — Qarkullimi 2021', 'Të dhëna të hapura — Qarkullimi 2021', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2022', 'ATK', 'Open Data — Qarkullimi 2022', 'Të dhëna të hapura — Qarkullimi 2022', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2023', 'ATK', 'Open Data — Qarkullimi 2023', 'Të dhëna të hapura — Qarkullimi 2023', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2024', 'ATK', 'Open Data — Qarkullimi 2024', 'Të dhëna të hapura — Qarkullimi 2024', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2025', 'ATK', 'Open Data — Qarkullimi 2025', 'Të dhëna të hapura — Qarkullimi 2025', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE);
