  (3, 'ATK', NULL, 'Aktivitetet e ekonomive familjare si punedhenes; Mallrat dhe sherbimet e padiferencuara, Aktivitetet e ekonomive familjare per perdorim vetanak', 'Household Employers', NULL, 'LOW', 'Households as employers; own-use production.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (4, 'ATK', NULL, 'Aktivitetet e patundshmerise', 'Real Estate', NULL, 'LOW', 'Transaction values sit far above normal card limits.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (5, 'ATK', NULL, 'Aktivitetet e shendetit te njeriut dhe te punes sociale', 'Human Health & Social Work', NULL, 'MEDIUM', 'Private clinics and pharmacies take cards; public provision does not.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (6, 'ATK', NULL, 'Aktivitetet e tjera sherbyese', 'Other Service Activities', NULL, 'HIGH', 'Personal services: hairdressing, repair, wellness.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (7, 'ATK', NULL, 'Aktivitetet e trupave dhe organizatave nderkombetare', 'International Organisations', NULL, 'LOW', 'Extraterritorial bodies.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (8, 'ATK', NULL, 'Aktivitetet financiare dhe te sigurimit', 'Financial & Insurance', NULL, 'LOW', 'Own payment rails; not merchant acquiring.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (9, 'ATK', NULL, 'Aktivitetet profesionale, shkencore dhe teknike', 'Professional, Scientific & Technical', NULL, 'MEDIUM', 'Mostly invoiced B2B, with a consumer-facing minority.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (10, 'ATK', NULL, 'Arsimi', 'Education', NULL, 'MEDIUM', 'Private tuition and course fees; public education is not a POS channel.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (11, 'ATK', NULL, 'Artet, Argetimi dhe rekreacioni', 'Arts, Entertainment & Recreation', NULL, 'HIGH', 'Consumer-facing leisure and entertainment venues.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (12, 'ATK', NULL, 'Bujqesia;Pylltaria dhe Peshkimi', 'Agriculture, Forestry & Fishing', NULL, 'LOW', 'Primary production sold to processors and wholesalers.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (13, 'ATK', NULL, 'Furnizimi me rryme, gaz, avull dhe  ajer te kondicionuar', 'Electricity, Gas & Air Conditioning', NULL, 'LOW', 'Utility billing, not point of sale.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (14, 'ATK', NULL, 'Furnizimi me uje; Kanalizimi; Aktivitetet e menaxhimit dhe te trajtimit te mbeturinave', 'Water Supply & Waste Management', NULL, 'LOW', 'Utility billing.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (15, 'ATK', NULL, 'Industria nxjerrese', 'Mining & Quarrying', NULL, 'LOW', 'Extractive, entirely B2B.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (16, 'ATK', NULL, 'Industria perpunuese', 'Manufacturing', NULL, 'LOW', 'Manufacturing output is sold B2B.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (17, 'ATK', NULL, 'Informimi dhe komunikimi', 'Information & Communication', NULL, 'MEDIUM', 'Telecom retail points take cards; most revenue is billed.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (18, 'ATK', NULL, 'Mungon aktiviteti', 'Activity Not Recorded', NULL, 'REVIEW_REQUIRED', 'No economic activity recorded by ATK; cannot be judged.', 'low', 'needs_review', 'v1.0', '2019-01-01', NULL),
  (19, 'ATK', NULL, 'Ndertimtaria', 'Construction', NULL, 'LOW', 'Contract and invoice based.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (20, 'ATK', NULL, 'Person Fizik', 'Natural Person (unclassified)', NULL, 'REVIEW_REQUIRED', 'A legal form rather than an activity; ATK records no sector for these.', 'low', 'needs_review', 'v1.0', '2019-01-01', NULL),
  (21, 'ATK', NULL, 'Sherbimet administrative dhe mbeshtetese', 'Administrative & Support Services', NULL, 'MEDIUM', 'Mixed; includes car rental and travel agencies, which are POS-facing.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (22, 'ATK', NULL, 'Transporti dhe magazinimi', 'Transport & Storage', NULL, 'MEDIUM', 'Passenger transport and courier counters are card-addressable; freight and warehousing are B2B.', 'medium', 'accepted', 'v1.0', '2019-01-01', NULL),
  (23, 'ATK', NULL, 'Tregtia me shumice dhe pakice; Riparimi i mjeteve motorike dhe motoeikletave', 'Wholesale & Retail Trade; Vehicle Repair', NULL, 'REVIEW_REQUIRED', 'Wholesale (B2B, not a POS channel) and retail (the most POS-addressable activity there is) are one NACE section worth ~46% of all turnover. ATK publishes no split, so no factor is invented. Reported separately; sets the ceiling of the addressable range.', 'low', 'needs_review', 'v1.0', '2019-01-01', NULL);
